WITH toegang AS (SELECT COALESCE((SELECT CAST(json_extract(o.parameters, '$.toegang_dagen') AS INTEGER) FROM organisatie o WHERE o.soort = 'eigen' AND o.deleted_at IS NULL ORDER BY o.id LIMIT 1), 30) AS dagen), dagen AS (SELECT productie_id, MIN(datum) AS eerste, MAX(datum) AS laatste FROM activiteit WHERE deleted_at IS NULL GROUP BY productie_id) SELECT MIN(t.id) AS id, t.persoon_id, a.productie_id, p.titel AS productie, replace(group_concat(DISTINCT r.naam ORDER BY r.naam), ',', ', ') AS rollen, d.eerste AS vanaf, d.laatste AS laatste_dag, date(d.laatste, '+' || toegang.dagen || ' days') AS toegang_vervalt, group_concat(t.notitie, '; ') AS notitie, per.dietary, MAX(r.dagtarief) AS dagtarief FROM toewijzing t JOIN activiteit a ON a.id = t.activiteit_id AND a.deleted_at IS NULL JOIN productie p ON p.id = a.productie_id AND p.deleted_at IS NULL JOIN persoon per ON per.id = t.persoon_id AND per.deleted_at IS NULL JOIN dagen d ON d.productie_id = a.productie_id CROSS JOIN toegang LEFT JOIN rol r ON r.id = t.rol_id AND r.deleted_at IS NULL WHERE t.deleted_at IS NULL AND t.state = 'bevestigd' GROUP BY t.persoon_id, a.productie_id HAVING date('now') <= toegang_vervalt
